mapper.select:
SELECT m.id, m.name, m.type, m.status,
       COALESCE(sf.url, '/static/default-logo.svg') AS logo_url
FROM merchant m
LEFT JOIN stored_file sf ON m.logo_file_id = sf.id


        AND m.name LIKE CONCAT(#{query.name}, '%')


        AND m.type = #{query.type}


        AND m.status = #{query.status}


ORDER BY m.id DESC
LIMIT #{page.offset}, #{page.size}

SELECT COUNT(*) FROM merchant m


        AND m.name LIKE CONCAT(#{query.name}, '%')


        AND m.type = #{query.type}


        AND m.status = #{query.status}
